BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-21863'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BL0042' OR source_url ~ '[?&]id=21863(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='512f5013-cd09-4e54-8e85-e506f151f82b' OR slug='sam-direct-sale-land-open-storage-shed-bang-lamung-1-bl0042' OR description ILIKE '%BL0042%' OR (abs(latitude-13.042709)<0.0001 AND abs(longitude-100.935201)<0.0001 AND abs(land_area_sqm-1884)<1)) THEN RAISE NOTICE 'SAM BL0042 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('512f5013-cd09-4e54-8e85-e506f151f82b', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'warehouse', 'business', 'sale', 'whole_property', 'ขายตรง SAM ที่ดินพร้อมโรงเก็บของโล่งหลังคาคลุม ซอยบางละมุง 1 ชลบุรี 471 ตร.ว.', 'ที่ดินพร้อมโรงเก็บของลักษณะส่วนโล่งหลังคาคลุม ไม่มีเลขที่ ซอยบางละมุง 1 ตำบลบางละมุง อำเภอบางละมุง จังหวัดชลบุรี โฉนดเลขที่ 36333 จำนวน 1 ฉบับ เนื้อที่ 1 ไร่ 71 ตร.ว. หรือ 471 ตร.ว. (1,884 ตร.ม.) ราคาประกาศขายจาก SAM 9,422,000 บาท รหัสทรัพย์ BL0042

ที่ดินรูปสี่เหลี่ยมคางหมู ด้านทิศเหนือติดถนน หน้ากว้างประมาณ 15 เมตร ลึกสุดประมาณ 120 เมตร ถนนหน้าทรัพย์คือซอยบางละมุง 1 เป็นทางสาธารณประโยชน์ ผิวคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 8 เมตร ต้นทางระบุเขตผังเมืองสีส้มและย่านที่อยู่อาศัย

รายการสิ่งปลูกสร้างตามทะเบียนที่ SAM รับโอนระบุโรงเก็บของชั้นเดียวไม่มีเลขที่ ส่วนการสำรวจระบุส่วนโล่งหลังคาคลุมไม่ติดเลขที่ ภาพแสดงอาคารหลังคาโครงเหล็กเปิดโล่ง จัดอยู่ในหมวดโกดัง/คลังสินค้าเพื่อค้นหา โดยต้องตรวจสภาพโครงสร้าง หลังคา พื้น และความเหมาะสมกับสินค้าที่จะจัดเก็บก่อนซื้อ ต้นทางไม่ระบุพื้นที่ใช้สอยหรือพื้นที่ใต้หลังคา

ผังแปลงแสดงโรงเก็บของอยู่ช่วงท้ายแปลง และมีแนวพื้นที่ยาวเชื่อมจากถนนด้านหน้า ควรตรวจแนวเขต ทางเข้าออก ความกว้างที่ใช้งานจริงและการกลับรถกับ SAM ไม่อนุมานว่ารถบรรทุกทุกขนาดเข้าออกได้

ต้นทางระบุว่าทรัพย์ห่างจากแนวโครงการต่อขยายรถไฟความเร็วสูงทางด้านตะวันออกประมาณ 530 เมตร ข้อมูลนี้เป็นระยะถึงแนวโครงการตาม SAM ไม่ใช่ระยะถึงสถานีหรือการยืนยันกำหนดเปิดบริการ ผู้สนใจควรตรวจตำแหน่งและสถานะโครงการปัจจุบันกับหน่วยงานเจ้าของโครงการ

การเดินทางตาม SAM: ใช้ถนนสุขุมวิท (ทล.3) จากตำบลทุ่งศุขลามุ่งหน้ามอเตอร์เวย์ชลบุรี–พัทยา ผ่านวัดศรีวนารามและโรงเรียนบ้านทุ่งกราด ถึงบริเวณ กม.132 เลี้ยวซ้ายเข้าซอยบางละมุง 1 ประมาณ 1 กิโลเมตร ทรัพย์อยู่ขวามือ สถานที่ใกล้เคียงที่ต้นทางระบุ ได้แก่ วัดท่ากระดาน โรงเรียนบ้านบางละมุง และโรงเรียนบ้านทุ่งกราด

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส BL0042 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม และเงื่อนไขล่าสุด

พิกัด 13.042709, 100.935201 ดึงจาก href ปุ่มระบบนำทางของ SAM และตรงกับปุ่ม Google Map ภาพจริงแสดงวันที่ 18 กรกฎาคม 2567 มีภาพหน้าแปลง แนวทางภายใน โรงเก็บของ ผัง และแผนที่ ต้นทางไม่ระบุสถานะผู้ครอบครอง กำลังไฟฟ้า ระบบประปา จำนวนที่จอดรถ อายุอาคาร ความสูงใต้หลังคา หรือกำลังรับน้ำหนักพื้น จึงควรตรวจข้อมูลเหล่านี้และสภาพปัจจุบันก่อนตัดสินใจ', 9422000, false, 1884, 1, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ซอยบางละมุง 1', 'เข้าจากถนนสุขุมวิท กม.132 ประมาณ 1 กิโลเมตร', 'ซอยบางละมุง 1', 13.042709, 100.935201, 'ชลบุรี', 'บางละมุง', 'บางละมุง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-land-open-storage-shed-bang-lamung-1-bl0042') RETURNING id INTO property_listing_id;
