INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=21863&keyref=6007623', 'BL0042', now(), 'Official source captured 2026-09-11. Direct purchase THB 9,422,000, 471 sq.wah. Registered single-storey storage building, surveyed open covered structure. Classified warehouse/storage, explicitly open-sided. Nine original images retained with dates 2024-07-18; actual shed image selected as cover. Source-reported 530 m distance is to railway project alignment, not station. Coordinates extracted from navigation href and cross-checked against map href. All-status duplicate check by code/page/deed/area/nearby coordinates found no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Land with Open Storage Shed, Bang Lamung 1, THB 9.422M', 'Land with an unnumbered open-sided covered storage structure in Soi Bang Lamung 1, Bang Lamung, Chon Buri. One title deed, no. 36333, covers 1 rai 71 sq.wah, equivalent to 471 sq.wah or 1,884 sq.m. SAM announced price THB 9,422,000; asset BL0042.

The trapezoidal plot has approximately 15 metres of northern frontage and a maximum depth of approximately 120 metres. Soi Bang Lamung 1 is a public concrete road approximately six metres wide within an eight-metre right of way. SAM reports orange planning zoning and residential surroundings.

SAM''s registered acquired structure is an unnumbered single-storey storage building. The survey describes an open-sided covered area, and photographs show an open steel-roof structure. It is listed under warehouse/storage for discovery. Check the structure, roof, floor and suitability for intended goods. Usable area and covered floor area are not published.

The source plan places the shed toward the rear, with a long approach from the front road. Confirm boundaries, access width and turning space; access for every truck size is not established.

SAM states that a high-speed railway extension alignment is approximately 530 metres to the east. This is a source-reported distance to a project alignment, not a station or an opening-date commitment. Confirm the current alignment and project status with the responsible authority.

Take Sukhumvit Road (Highway 3) from Thung Sukhla toward the Chon Buri–Pattaya motorway, passing Wat Si Wanaram and Ban Thung Krat School. Around kilometre 132, turn left into Soi Bang Lamung 1 for approximately one kilometre; the property is on the right. Source-listed nearby places include Wat Tha Kradan, Ban Bang Lamung School and Ban Thung Krat School.

SAM showed direct-purchase status and this price on 11 September 2026. Contact 02-686-1888, sales@sam.or.th or LINE @samline, quoting BL0042, to confirm availability, price, viewing and terms.

Coordinates 13.042709, 100.935201 come directly from the SAM navigation href and agree with its map link. Photos display 18 July 2024. Occupancy, electrical capacity, water supply, parking count, age, clear height and floor loading are not published; inspect current conditions.', 'Soi Bang Lamung 1', 'Approx. 1 km from Sukhumvit Road at km 132', 'Soi Bang Lamung 1', 'Bang Lamung', 'Bang Lamung', 'Chon Buri', 'SAM Land with Open Storage Shed, Bang Lamung — THB 9.422M', 'SAM BL0042: 471 sq.wah with an open-sided storage shed in Soi Bang Lamung 1. Approx. 15 m frontage and 120 m maximum depth.', 'published', 'ai_assisted', now(), 'sam direct sale: land with open storage shed, bang lamung 1, thb 9.422m land with an unnumbered open-sided covered storage structure in soi bang lamung 1, bang lamung, chon buri. one title deed, no. 36333, covers 1 rai 71 sq.wah, equivalent to 471 sq.wah or 1,884 sq.m. sam announced price thb 9,422,000; asset bl0042.

the trapezoidal plot has approximately 15 metres of northern frontage and a maximum depth of approximately 120 metres. soi bang lamung 1 is a public concrete road approximately six metres wide within an eight-metre right of way. sam reports orange planning zoning and residential surroundings.

